// src/lib/mcp/tools/resumo-financeiro.ts
import { defineTool as defineTool8 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z8 } from "npm:zod@^3.25.76";
function summarize(rows) {
  let receitas = 0;
  let despesas = 0;
  const porCategoria = {};
  for (const r of rows) {
    const valor = Number(r.valor) || 0;
    if (r.tipo === "receita") receitas += valor;
    else {
      despesas += valor;
      const key = r.categoria ?? "Sem categoria";
      porCategoria[key] = (porCategoria[key] ?? 0) + valor;
    }
  }
  return {
    receitas,
    despesas,
    saldo: receitas - despesas,
    despesas_por_categoria: Object.entries(porCategoria).sort((a, b) => b[1] - a[1]).map(([categoria, total]) => ({ categoria, total }))
  };
}
var resumo_financeiro_default = defineTool8({
  name: "resumo_financeiro",
  title: "Resumo financeiro do per\xEDodo",
  description: "Calcula receitas, despesas, saldo e despesas por categoria em um per\xEDodo, para as finan\xE7as pessoais (PF) ou da empresa (PJ).",
  inputSchema: {
    escopo: z8.enum(["pf", "pj"]).describe("pf para finan\xE7as pessoais, pj para a empresa."),
    from: z8.string().describe("Data inicial no formato YYYY-MM-DD."),
    to: z8.string().describe("Data final no formato YYYY-MM-DD.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ escopo, from, to }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "N\xE3o autenticado." }], isError: true };
    }
    const supabase = supabaseForUser(ctx);
    const table = escopo === "pf" ? "pf_transacoes" : "lancamentos";
    const { data, error } = await supabase.from(table).select("tipo,valor,categoria").gte("data", from).lte("data", to).limit(5e3);
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    const resumo = { escopo, from, to, ...summarize(data ?? []) };
    return {
      content: [{ type: "text", text: JSON.stringify(resumo) }],
      structuredContent: resumo
    };
  }
});

